SELECT dc.deployment_date, l.location_name, c.item_name, c.fixture_family, c.size, pa.reset_lead, pa.priority, CASE WHEN ii.cleared_for_use = TRUE THEN 'Ready' WHEN ii.result = 'Fail' THEN 'Needs Restock' WHEN ii.result = 'Pending' THEN 'Inspection Pending' WHEN ii.inspection_id IS NULL THEN 'Not Yet Inspected' ELSE 'Unknown' END AS readiness_status FROM store_ops.deployment_calendar dc JOIN store_ops.catalog c ON dc.item_id = c.item_id JOIN store_ops.locations l ON dc.location_id = l.location_id LEFT JOIN store_ops.pre_allocations pa ON dc.allocation_id = pa.allocation_id LEFT JOIN store_ops.retrieval_schedule rs ON rs.deployment_id = dc.allocation_id LEFT JOIN store_ops.fixture_inspections ii ON ii.retrieval_id = rs.retrieval_id AND ii.item_id = c.item_id WHERE c.item_type = 'Fixture' ORDER BY dc.deployment_date, pa.priority DESC;